#!/usr/bin/env node
// Task 1565 — generates e2e/maestro/1565-preview-matrix/run.yaml from
// e2e/scripts/preview-matrix-fixtures.mjs, so the 59-fixture sequence is
// mechanically derived from ONE source of truth (also used by the seeding
// script) instead of hand-transcribed 59 times with room for copy-paste
// drift between the uploaded filename and the flow's own expectation.
//
// The generated file is committed like any other flow — this script is a
// maintenance tool you re-run after editing preview-matrix-fixtures.mjs, not
// a runtime dependency of the test itself.
//
// Usage: node e2e/scripts/gen-preview-matrix-flow.mjs

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { FIXTURES } from './preview-matrix-fixtures.mjs'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const OUT_PATH = path.join(__dirname, '..', 'maestro', '1565-preview-matrix', 'run.yaml')

function uploadNameFor(n, origBase) {
  if (origBase === 'Dockerfile') return origBase
  return `${String(n).padStart(2, '0')}-${origBase}`
}

const header = `# GENERATED by e2e/scripts/gen-preview-matrix-flow.mjs from
# e2e/scripts/preview-matrix-fixtures.mjs — do not hand-edit the per-fixture
# blocks below; edit the fixtures table and re-run the generator instead.
#
# Task 1565 — mobile preview matrix, full run.
#
# PRECONDITIONS:
#   1. e2e/scripts/seed-preview-matrix-web.mjs has already uploaded every
#      fixture to qa0688content@beebeeb.io's Drive (local API/DB only).
#   2. The target simulator is booted, signed in as that account, on Drive,
#      pointed at the LOCAL API (Metro log: "API environment: ... localhost:3001").
#      e2e/maestro/local-qa-signin-unlock.yaml gets a cold app to that state.
#   3. This lane holds the machine-wide Maestro driver (CLAUDE.md "One
#      \`maestro test\` at a time").
#
# Run via e2e/scripts/run-preview-matrix.sh (sets --udid, EVIDENCE_DIR, and
# writes the PASS/FAIL summary this task's own Verification field asks for)
# — do not invoke this file directly with a bare \`maestro test\`.
appId: io.beebeeb.app
---
- tapOn: "Files"
- extendedWaitUntil:
    visible: "Drive"
    timeout: 15000
`

const blocks = FIXTURES.map((fx, i) => {
  const n = i + 1
  const origBase = path.basename(fx.rel)
  const uploadName = uploadNameFor(n, origBase)
  const shotName = `1565-${String(n).padStart(2, '0')}-${fx.category}-${fx.ext.replace(/[^\w.-]/g, '_')}`
  // Single-quoted YAML scalars (not double-quoted): the escaped dots below
  // (\.) are a backslash-escape in the REGEX Maestro's text matcher
  // evaluates, not in YAML string syntax — YAML double-quoted scalars only
  // allow a fixed, known set of \-escapes and reject `\.` outright ("found
  // unknown escape character '.'"), while single-quoted scalars pass
  // backslashes through completely literally. Caught by validating this
  // generated file with a YAML parser before it was ever committed.
  const fileNameRegex = uploadName.replace(/\./g, '\\.')
  return `
# ${n}/${FIXTURES.length} — ${fx.rel} (expects: ${fx.expectedIdRegex}) — ${fx.notes}
- runFlow:
    file: _open-and-check.yaml
    env:
      FILE_NAME: '${fileNameRegex}'
      EXPECT_ID_REGEX: '${fx.expectedIdRegex}'
      SHOT_NAME: '${shotName}'`
}).join('\n')

fs.writeFileSync(OUT_PATH, header + blocks + '\n')
console.log(`[gen-1565] wrote ${OUT_PATH} (${FIXTURES.length} fixtures)`)
